namespace sv_899991b4e2bb4b32b6fbd431e112a109.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Because it is registered as Scoped, each SignalR circuit (user) gets its own instance.
/// The circuit persists across enhanced navigations, so state survives page changes.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0078d4";

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetPreferences(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@* 
    Interactive island in the static layout.
    Because this has @rendermode InteractiveServer, it stays connected to the circuit
    and re-renders immediately when ThemeService fires OnChange.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme</label>
        <select @bind="selectedTheme" @bind:after="ApplyChanges">
            @foreach (var theme in Enum.GetValues<Theme>())
            {
                <option value="@theme">@theme</option>
            }
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="selectedAccentColor" @bind:after="ApplyChanges" />
        <span style="color: @selectedAccentColor;">@selectedAccentColor</span>
    </div>
</div>

<p class="theme-preview" style="border-left: 4px solid @selectedAccentColor;">
    Current theme: <strong>@ThemeService.CurrentTheme</strong> with accent
    <strong>@ThemeService.AccentColor</strong>
</p>

@code {
    private Theme selectedTheme;
    private string selectedAccentColor = "#0078d4";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.CurrentTheme;
        selectedAccentColor = ThemeService.AccentColor;
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void ApplyChanges()
    {
        ThemeService.SetPreferences(selectedTheme, selectedAccentColor);
    }

    private void HandleThemeChanged()
    {
        selectedTheme = ThemeService.CurrentTheme;
        selectedAccentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

